1	/**
2	 * The doorbell.
3	 *
4	 * A device with a run open holds one socket to the server and says which
5	 * session it is watching. When another device changes that session the
6	 * server sends one line, "changed, seq 12", and this device syncs at
7	 * once instead of at the next poll. Nothing else travels here: the moves
8	 * still come down the same authenticated fetch as before, so a socket
9	 * that lies can only cause a fetch that finds nothing new.
10	 *
11	 * Sockets close for a hundred reasons, a laptop lid, a tunnel, a deploy,
12	 * so this one reconnects with a backoff that starts at a second and stops
13	 * growing at half a minute, re-sends its watch on every open, and fetches
14	 * a fresh token for each attempt, since the last one may have expired
15	 * while the lid was shut. Polling carries on underneath at a slower pace,
16	 * and takes over entirely while the socket is down.
17	 */
18	
19	export interface Changed {
20	  t: "changed";
21	  id: string;
22	  seq: number;
23	}
24	
25	export interface LiveSocket {
26	  /** Watch this session; re-sent after every reconnect. Null to watch nothing. */
