16	  disconnect(): void;
17	  press(p: { press: string; move?: string; answer?: Record<string, unknown> }): string | null;
18	}
19	
20	/** The app's own rule: a second, doubling, capped at half a minute, with a little jitter. */
21	function backoffMs(attempt: number, random: () => number): number {
22	  return Math.min(30_000, 1000 * 2 ** attempt) * (0.8 + random() * 0.4);
23	}
24	
25	/**
26	 * One socket to Runlog, as a deck.
27	 *
28	 * It attaches signed in and names no run; the server pushes the held
29	 * list, the store picks, and this watches whichever it picked so the
30	 * doorbell rings here too. A ring is a fetch of the snapshot on the
31	 * signed-in route, which is where the offer is. A press names the run
32	 * and the offer's `seq`, so the page can refuse one the run has moved
33	 * past.
34	 *
35	 * The account may be a getter, resolved again on every connect and every
36	 * fetch: the address is a setting the streamer can change, and the one that
37	 * counts is the one it reads when the streamer presses Connect.
38	 */
39	export function openWire(account: Account | (() => Account), store: Store, deps: WireDeps = realDeps()): Wire {
40	  let socket: WebSocket | null = null;
41	  let wanted = false;
42	  let attempt = 0;
43	  let watching: string | null = null;
44	  // Which dialing attempt is the live one. A real close is asynchronous, so
45	  // Reconnect - close, then dial again - leaves the old socket's handlers
46	  // queued behind the new socket's. Each attempt captures the number it was
47	  // given and any handler whose number has moved on does nothing: no state
48	  // dispatched from a socket nobody is using, and no backoff reopen racing
49	  // the connect that replaced it.
50	  let generation = 0;
51	  const currentAccount = (): Account => (typeof account === "function" ? account() : account);
52	
53	  const fetchSnapshot = async (run: string) => {
54	    // The same rule as the socket handlers: numbers taken at the start, and
55	    // an answer that arrives after the connection it was asked for is gone
56	    // belongs to nobody.
57	    const mine = generation;
58	    const acct = currentAccount();
59	    const token = await deps.bearer(acct);
60	    if (!token || mine !== generation) return;
61	    try {
62	      const res = await deps.fetch(`${normalizeBase(acct.apiBase)}/api/sessions/${encodeURIComponent(run)}/snapshot`, {
63	        headers: { authorization: `Bearer ${token}` },
64	      });
65	      if (res.ok && mine === generation) store.dispatch({ t: "snapshot", snapshot: (await res.json()) as never });
66	    } catch {
67	      /* the next ring tries again */
68	    }
69	  };
70	
71	  const follow = () => {
72	    const run = attachedRun(store.state);
73	    if (run === watching || !socket) return;
74	    watching = run;
75	    if (run) {
76	      socket.send(JSON.stringify({ t: "watch", id: run }));
77	      void fetchSnapshot(run);
78	    }
79	  };
80	  store.subscribe(follow);
81	
82	  const open = async () => {
83	    if (!wanted) return;
84	    const mine = ++generation;
85	    const acct = currentAccount();
86	    const token = await deps.bearer(acct);
87	    // Before any dispatch, not after the token check: a refusal belonging to
88	    // a dial that has been superseded would otherwise report the session
89	    // lapsed and reset the state out from under the connection that replaced
90	    // it. A superseded connect touches nothing.
91	    if (mine !== generation) return;
92	    if (!token) {
93	      store.dispatch({ t: "session", state: "expired" });
94	      return;
95	    }
96	    store.dispatch({ t: "socket", state: "connecting" });
97	    const wsBase = normalizeBase(acct.apiBase).replace(/^http/, "ws");
98	    const ws = new deps.WebSocket(`${wsBase}/ws?token=${encodeURIComponent(token)}&as=deck`);
99	    socket = ws;
100	    ws.onopen = () => {
101	      if (mine !== generation) return;
102	      attempt = 0;
103	      watching = null;
104	      store.dispatch({ t: "socket", state: "open" });
105	      ws.send(JSON.stringify({ t: "hello" }));
106	    };
107	    ws.onmessage = (e) => {
108	      if (mine !== generation) return;
109	      let m: unknown;
110	      try {
111	        m = JSON.parse(String(e.data));
112	      } catch {
113	        return;
114	      }
115	      if (typeof m !== "object" || m === null) return;
116	      const msg = m as Record<string, unknown>;
117	      if (msg["t"] === "runs" && Array.isArray(msg["runs"])) {
118	        const runs = msg["runs"].filter(
119	          (r): r is { id: string } => typeof r === "object" && r !== null && typeof (r as Record<string, unknown>)["id"] === "string",
120	        );
121	        store.dispatch({ t: "runs", runs: runs as never, any: msg["any"] === true });
122	      } else if (msg["t"] === "changed" && msg["id"] === watching && watching) void fetchSnapshot(watching);
123	      else if (msg["t"] === "drove" && typeof msg["ref"] === "string")
124	        store.dispatch({
125	          t: "drove",
126	          ref: msg["ref"],
127	          ok: msg["ok"] === true,
128	          ...(typeof msg["say"] === "string" ? { say: msg["say"] } : {}),
129	          ...(typeof msg["seq"] === "number" ? { seq: msg["seq"] } : {}),
130	        });
131	    };
132	    ws.onclose = () => {
133	      if (mine !== generation) return;
134	      socket = null;
135	      store.dispatch({ t: "socket", state: "closed" });
136	      if (wanted) setTimeout(() => void open(), backoffMs(attempt++, deps.random));
137	    };
138	  };
139	
140	  return {
141	    connect() {
142	      wanted = true;
143	      void open();
144	    },
145	    disconnect() {
146	      wanted = false;
147	      // Retiring the generation first: whatever this socket does on its way
148	      // down is no longer anybody's business.
149	      generation++;
150	      const going = socket;
151	      socket = null;
152	      store.dispatch({ t: "socket", state: "closed" });
153	      going?.close();
154	    },
155	    press(p) {
156	      const run = attachedRun(store.state);
157	      const seq = store.state.snapshot?.offer?.seq;
158	      if (!run || seq === undefined || !socket) return null;
159	      const ref = `sd-${deps.now().toString(36)}-${Math.floor(deps.random() * 1e6).toString(36)}`;
160	      socket.send(JSON.stringify({ t: "drive", run, seq, ref, ...p }));
161	      return ref;
162	    },
163	  };
164	}
165	
166	function realDeps(): WireDeps {
167	  return {
168	    WebSocket: globalThis.WebSocket,
169	    fetch: (i, o) => fetch(i, o),
170	    bearer: realBearer,
171	    now: () => Date.now(),
172	    random: () => Math.random(),
173	  };
174	}
