          t: "drove",
          ref: msg["ref"],
          ok: msg["ok"] === true,
          ...(typeof msg["say"] === "string" ? { say: msg["say"] } : {}),
          ...(typeof msg["seq"] === "number" ? { seq: msg["seq"] } : {}),
        });
    };
