import { describe, expect, it, vi } from "vitest";
import {
  backoffMs,
  openLive,
  parseChanged,
  parseDrive,
  parseGesture,
  socketUrl,
  type Changed,
  type Drive,
  type Gesture,
} from "./socket.ts";

/**
 * A pretend socket: opened, closed and spoken to by the test, so the
 * reconnect and re-watch can be watched without a network.
 */
class FakeSocket {
  static all: FakeSocket[] = [];
  sent: string[] = [];
  closed = false;
  onopen: (() => void) | null = null;
  onmessage: ((e: { data: unknown }) => void) | null = null;
  onclose: (() => void) | null = null;
  onerror: (() => void) | null = null;
  constructor(public url: string) {
    FakeSocket.all.push(this);
  }
  send(data: string) {
    this.sent.push(data);
  }
  close() {
    this.closed = true;
    this.onclose?.();
  }
}

/** Waits that a test releases by hand, in order. */
function manualClock() {
  const pending: Array<{ ms: number; fn: () => void }> = [];
  return {
    pending,
    wait: (ms: number, fn: () => void) => {
      const entry = { ms, fn };
      pending.push(entry);
      return () => {
        const i = pending.indexOf(entry);
        if (i >= 0) pending.splice(i, 1);
      };
    },
    fire() {
      const next = pending.shift();
      next?.fn();
    },
  };
}

